// @scaleflex/dam-core — raw Filerobot browse endpoints.
//
// The "raw" counterpart to files.service / folders.service: these return the Filerobot wire
// response un-normalized (FilerobotAsset / FilerobotFolder), for consumers that need full
// fidelity — `@scaleflex/asset-picker` returns the raw object on select. Query-building mirrors
// what asset-picker shipped (verified against the live API); the normalized getFilesPage /
// getFolders remain the right choice for the headless core + light-dam. See plan/12 Wave 3.
import type { DamClient } from './dam-client';
import type { FilerobotAsset, FilerobotFolder } from '../types/filerobot.types';

/** Computed Files API fields requested by default (signed CDN permalink). Additive on the wire. */
const DEFAULT_API_FIELDS = ['cdn_permalink'];

export interface FilerobotFilesParams {
  folder?: string;
  offset?: number;
  limit?: number;
  sort_by?: string;
  sort_direction?: string;
  /** Free-text search. */
  search?: string;
  /** Pre-serialized search/filter notation. */
  q?: string;
  recursive?: number;
  /** Enable AI-powered semantic search. */
  with_ai?: boolean;
  ai_query?: string;
  ai_lang?: string;
  /** Filter by collection. */
  collection_uuid?: string;
  /** Base64-encoded collection-folder filter. */
  f64?: string;
  /** Extra computed fields (e.g. `cdn_permalink`); undefined → the default set. */
  fields?: string[];
  /** Project-level toggle — `cdn_permalink` is stripped from `fields` when false. */
  permalinksEnabled?: boolean;
}

export interface FilerobotFilesResponse {
  status: string;
  msg?: string;
  files: FilerobotAsset[];
  folders: FilerobotFolder[];
  base?: {
    count?: {
      files_direct?: number;
      files_recursive?: number;
    };
  };
  info?: {
    total_files_count?: number;
    total_files_size?: number;
  };
  limit: number;
  offset: number;
}

const SORT_FIELDS: Record<string, string> = {
  created_at: 'created_at',
  modified_at: 'modified_at',
  name: 'name',
  size: 'size',
  type: 'type',
};

function buildFilesQuery(params: FilerobotFilesParams): Record<string, unknown> {
  let fields = params.fields ?? DEFAULT_API_FIELDS;
  if (!params.permalinksEnabled) {
    fields = fields.filter((field) => field !== 'cdn_permalink');
  }
  const apiParams: Record<string, unknown> = {
    offset: params.offset ?? 0,
    limit: params.limit ?? 100,
    format: 'json,regvar:api,select:internal',
    preview: 2301,
    recursive: params.recursive ?? 1,
  };
  if (fields.length > 0) apiParams.fields = fields;

  const sortField = params.sort_by ?? 'created_at';
  const sortDir = params.sort_direction ?? 'desc';
  apiParams.sort = `${SORT_FIELDS[sortField] || sortField}:${sortDir}`;

  if (params.folder) apiParams.folder = params.folder;

  // With AI search active the text goes in ai_query, not q.
  const parts: string[] = [];
  if (params.search && !params.with_ai) parts.push(params.search);
  if (params.q) parts.push(params.q);
  if (parts.length > 0) apiParams.q = parts.join(' ');

  if (params.with_ai) {
    apiParams.with_ai = true;
    if (params.ai_query) apiParams.ai_query = params.ai_query;
    if (params.ai_lang) apiParams.ai_lang = params.ai_lang;
  }
  if (params.collection_uuid) apiParams.collection_uuid = params.collection_uuid;
  if (params.f64) apiParams.f64 = params.f64;

  return apiParams;
}

/** Fetch a page of files as the raw Filerobot wire response (no normalization). */
export function getFilesRaw(
  client: DamClient,
  params: FilerobotFilesParams,
): Promise<FilerobotFilesResponse> {
  return client.get<FilerobotFilesResponse>('/files', buildFilesQuery(params));
}

export interface FilerobotFilesStatsResponse {
  status: string;
  stats?: {
    approx_files_count?: number;
    approx_files_size?: number;
  };
  info?: {
    total_files_count?: number;
    total_files_size?: number;
  };
}

export type FilerobotFilesStatsParams = Pick<
  FilerobotFilesParams,
  'folder' | 'q' | 'search' | 'recursive' | 'with_ai' | 'ai_query' | 'ai_lang' | 'collection_uuid' | 'f64'
>;

/** Approximate file count/size for a scope (the `/files/stats` endpoint). */
export function getFilesStats(
  client: DamClient,
  params: FilerobotFilesStatsParams,
): Promise<FilerobotFilesStatsResponse> {
  const apiParams: Record<string, unknown> = { recursive: params.recursive ?? 1 };
  if (params.folder) apiParams.folder = params.folder;
  const parts: string[] = [];
  if (params.search && !params.with_ai) parts.push(params.search);
  if (params.q) parts.push(params.q);
  if (parts.length > 0) apiParams.q = parts.join(' ');
  if (params.with_ai) {
    apiParams.with_ai = true;
    if (params.ai_query) apiParams.ai_query = params.ai_query;
    if (params.ai_lang) apiParams.ai_lang = params.ai_lang;
  }
  if (params.collection_uuid) apiParams.collection_uuid = params.collection_uuid;
  if (params.f64) apiParams.f64 = params.f64;
  return client.get<FilerobotFilesStatsResponse>('/files/stats', apiParams);
}

export interface FilerobotFoldersParams {
  folderPath?: string;
  recursive?: number;
  limit?: number;
  offset?: number;
  q?: string;
  sort_by?: string;
  sort_direction?: string;
}

export interface FilerobotFoldersResponse {
  status: string;
  msg?: string;
  folders: FilerobotFolder[];
  total?: number;
}

/** Fetch folders as the raw Filerobot wire response (no normalization). */
export function getFoldersRaw(
  client: DamClient,
  params: FilerobotFoldersParams = {},
): Promise<FilerobotFoldersResponse> {
  const apiParams: Record<string, unknown> = {
    recursive: params.recursive ?? 0,
    folder: params.folderPath ?? '/',
    limit: params.limit ?? 1000,
    offset: params.offset ?? 0,
  };
  if (params.q) apiParams.q = params.q;
  const sortField = params.sort_by ?? 'created_at';
  const sortDir = params.sort_direction ?? 'asc';
  apiParams.sort = `${SORT_FIELDS[sortField] || sortField}:${sortDir}`;
  return client.get<FilerobotFoldersResponse>('/folders', apiParams);
}

export interface FolderPreview {
  file_uuid: string;
  file_uri_cdn: string;
  file_type: string;
  preview_origin: string;
}

interface FolderPreviewsResponse {
  status: string;
  folders: Record<string, FolderPreview[]>;
}

/** Preview thumbnails for a set of folders (`POST /folders/previews`). */
export async function getFolderPreviews(
  client: DamClient,
  folderUuids: string[],
): Promise<Record<string, FolderPreview[]>> {
  if (folderUuids.length === 0) return {};
  const res = await client.post<FolderPreviewsResponse>('/folders/previews', {
    folders: folderUuids,
  });
  return res.folders || {};
}
