import { LitElement, html, css } from 'lit';
import { property, state } from 'lit/decorators.js';
import { customElement } from '../utils/define-element';

/**
 * Lightweight popover: a `slot="trigger"` button toggles a content panel (default slot).
 * Dismisses on outside-click or Escape. `align` controls horizontal anchoring — `start`
 * (default) opens from the left edge, `end` from the right (for triggers near the viewport's
 * right edge). The content panel can set its own width/max-height/overflow.
 */
@customElement('sfx-popover')
export class SfxPopover extends LitElement {
  static styles = [
    css`
      :host {
        position: relative;
        display: inline-block;
      }
      .content {
        display: none;
        position: absolute;
        top: calc(100% + 4px);
        left: 0;
        z-index: 50;
        min-width: 200px;
        background: var(--sfx-card, oklch(1 0 0));
        border: 1px solid var(--sfx-border, oklch(92.86% 0.009 247.92));
        border-radius: var(--sfx-radius, 8px);
        box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        padding: 8px;
      }
      .content.end {
        left: auto;
        right: 0;
      }
      .content.open {
        display: block;
      }
    `,
  ];

  @state() open = false;
  /** Horizontal anchor: `start` opens from the left edge, `end` from the right. */
  @property() align: 'start' | 'end' = 'start';

  render() {
    return html`
      <slot name="trigger" @click=${() => (this.open = !this.open)}></slot>
      <div class="content ${this.align === 'end' ? 'end' : ''} ${this.open ? 'open' : ''}">
        <slot></slot>
      </div>
    `;
  }

  connectedCallback() {
    super.connectedCallback();
    document.addEventListener('click', this._handleOutsideClick);
    document.addEventListener('keydown', this._handleKeyDown);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    document.removeEventListener('click', this._handleOutsideClick);
    document.removeEventListener('keydown', this._handleKeyDown);
  }

  private _handleOutsideClick = (e: Event) => {
    if (this.open && !e.composedPath().includes(this)) {
      this.open = false;
    }
  };

  private _handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Escape' && this.open) {
      this.open = false;
    }
  };
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-popover': SfxPopover;
  }
}
