// Debounce a void-returning function: collapses bursts of calls into one,
// firing `delay` ms after the last call. The returned function carries a
// `.cancel()` to drop a pending trailing call (e.g. on disconnect). Shared so
// every DAM widget debounces search/scroll/resize the same way.

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function debounce<T extends (...args: any[]) => void>(
  fn: T,
  delay: number,
): T & { cancel(): void } {
  let timer: ReturnType<typeof setTimeout>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const debounced = ((...args: any[]) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  }) as T & { cancel(): void };
  debounced.cancel = () => clearTimeout(timer);
  return debounced;
}
